"""Inspect EN4B/RDCR source and original callback candidate without firmware execution."""
import argparse,hashlib,json,struct,subprocess
from pathlib import Path
from capstone import Cs,CS_ARCH_ARM,CS_MODE_THUMB,CS_MODE_MCLASS
from pypdf import PdfReader
from pinned_main import load_pinned_main
from native_replay import parse_log

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('simulator',type=Path);p.add_argument('output',type=Path);a=p.parse_args();s=a.simulator;o=a.output;o.mkdir(mode=0o700);checks=[];cases=[]
 def check(n,v):
  if not v:raise ValueError(n)
  checks.append(n)
 pdf=s/'mspi1-pio-research-01/mx25u25643g-v1.1.pdf';pin=json.loads((pdf.parent/'datasheet-source.json').read_text());check('manufacturer-PDF-pin',hashlib.sha256(pdf.read_bytes()).hexdigest()==pin['sha256']);r=PdfReader(pdf);texts={n:r.pages[n-1].extract_text() for n in [21,33,37,38,43,90]}
 for n,t in texts.items():(o/f'datasheet-page-{n}.txt').write_text(t)
 t=' '.join(texts[43].split());check('EN4B-bit5-and-reset-exit','bit5 (4BYTE bit)' in t and 'EX4B) instruction, Reset or power-off' in t and 'address length becomes 32-bit' in t);check('no-WREN-precondition-stated-on-EN4B-page','WREN' not in t and 'WEL' not in t);t=' '.join(texts[33].split());check('RDCR-15-and-sequence','15h' in t and 'sending RDCR instruction code→ Configuration Register data out on SO.' in t);t=' '.join(texts[37].split());check('CR-volatility-distinction','ODS2, ODS1, ODS0) bits are volatile bits' in t and 'TB) bit is a non-volatile OTP bit' in t and 'Preamble Bit Enable (PBE) bit is a volatile bit' in t);t=' '.join(texts[38].split());check('ODS-and-DC-defaults','0 0 0 30 Ohms (Default)' in t and '00 (default)' in t)
 md=Cs(CS_ARCH_ARM,CS_MODE_THUMB|CS_MODE_MCLASS)
 for key,bundle,delta in [('stock24','stock-2.4.0.24.bin',0),('stock23','stock-2.3.0.24.bin',0x4d18),('cfw','faceclaw-38-research-only.bin',0x4d18)]:
  d=s/'mspi1-write-enable-main-01'/key;_,raw=load_pinned_main((s/'inputs/verified-01'/bundle).read_bytes());check(key+'-original-main',raw==(d/'main.bin').read_bytes());log=(d/'renode.log').read_text();v=parse_log(log);check(key+'-saved-report',v==json.loads((d/'report.json').read_text())['observed']);cfg=[json.loads(x.split(' ',1)[1])['registers'] for x in log.splitlines() if x.startswith('BLACKWALL_MSPI1_CONFIG ')];g=[x for x in v['guards'] if x['accesses']];check(key+'-B7-request',len(cfg)==1 and cfg[0]['12']==0xb7 and cfg[0]['132']==0x3010061 and len(g)==1 and g[0]['address']==0x40061000 and g[0]['value']==0xc1);st=v['stack_context'];b=struct.pack('<32I',*st['words']);off=v['register_context']['r1']-st['base'];check(key+'-command-only-descriptor',off==36 and b[off:off+24]==bytes.fromhex('0000000000000100000000000100b7000000000000000000'))
  parent=0x47ba04-delta;code=list(md.disasm(raw[parent-0x438000:parent+0x1b4-0x438000],parent));m={x.address:(x.mnemonic,x.op_str) for x in code};expected={0:('push','{r2, r3, r4, lr}'),0xbe:('bl','#'+hex(0x47b694-delta)),0xc2:('movs','r4, r0'),0xc4:('cmp','r4, #0'),0xc6:('beq','#'+hex(parent+0x10c)),0x10c:('bl','#'+hex(0x47b832-delta)),0x114:('ldr','r0, [r0]'),0x116:('ldr','r0, [r0, #0xc]'),0x118:('blx','r0'),0x11a:('cmp','r0, #0'),0x11c:('bne','#'+hex(parent+0x162))};check(key+'-parent-transfer-poll-indirect-check',all(m.get(parent+x)==pair for x,pair in expected.items()));entry=0x47b83e-delta;tail=0x47b8fe-delta;code2=list(md.disasm(raw[entry-0x438000:tail-0x438000],entry));m2={x.address:(x.mnemonic,x.op_str) for x in code2};expected2={0:('push','{r0, r1, r2, r3, r4, lr}'),0xc:('movs','r0, #1'),0x10:('add','r3, sp, #8'),0x12:('movs','r2, #0'),0x14:('movs','r1, #0'),0x16:('movs','r0, #0x15'),0x18:('bl','#'+hex(0x47b5e0-delta)),0x1e:('cmp','r4, #0'),0x20:('beq','#'+hex(entry+0x6a)),0x6a:('ldrb.w','r0, [sp, #8]'),0x6e:('lsls','r0, r0, #0x1a'),0x70:('bpl','#'+hex(entry+0x76)),0x72:('movs','r0, #1'),0x74:('b','#'+hex(entry+0xbc)),0xba:('movs','r0, #0'),0xbc:('add','sp, #0x10'),0xbe:('pop','{r4, pc}')};check(key+'-candidate-RDCR-RX1-bit5-check',all(m2.get(entry+x)==pair for x,pair in expected2.items()));(o/(key+'-address-mode.asm')).write_text('\n'.join(hex(x.address)+' '+x.mnemonic+' '+x.op_str for x in code+code2)+'\n');cases.append(dict(case=key,parent=hex(parent),candidate_RDCR_helper=hex(entry),B7_completed=False,indirect_target_verified_at_runtime=False))
 (o/'report.json').write_text(json.dumps(dict(passed=True,count=len(checks),checks=checks,cases=cases,scope='manufacturer address-mode contract and static original callback candidate; no mode switch, callback execution, memory addressing or physical proof'),indent=2)+'\n');print(json.dumps(dict(passed=True,count=len(checks))))
if __name__=='__main__':main()
